window.MLFF_MODEL = {"id":"sevennet","name":"SevenNet","fullName":"SevenNet: Scalable EquiVariance-Enabled Neural Network","year":2024,"authors":"Y. Park, J. Kim, S. Hwang, S. Han","paper":{"title":"Scalable Parallel Algorithm for Graph Neural Network Interatomic Potentials in Molecular Dynamics Simulations","venue":"J. Chem. Theory Comput. 20(11), 4857–4868 (2024)","url":"https://doi.org/10.1021/acs.jctc.4c00190"},"repos":["SevenNet"],"family":"spherical-equivariant","tags":["E(3) 等变（NequIP 式）","球谐张量积卷积","LAMMPS 多 GPU 空间分解","多保真度 / 多任务","CUDA D3 色散"],"framework":"PyTorch + e3nn（可选 FlashTP / cuEquivariance / OpenEquivariance / LunaTP 内核）；LAMMPS C++/CUDA 接口","license":"MIT（LAMMPS pair_e3gnn / pair_d3 源文件按 LAMMPS 惯例为 GPL；Matbench 记录早期版本为 GPL-3.0）","oneLiner":"以 NequIP 的球谐张量积卷积为核心的等变消息传递势：把自连接里元素相关的张量积换成线性层大幅减参，并为消息传递网络专门设计了 LAMMPS 空间分解并行（每层交换 ghost 原子特征、反向逐层回传梯度）；MF/Omni 版本再加一个“任务/泛函”标签，让同一网络同时学多种 DFT 设定。","analogy":"像一支分区作业的传话队伍：整块材料被切成许多区域，每块交给一张 GPU；每传一轮话（一层卷积）之前，相邻区域先互相抄送“边界原子的最新笔记”（ghost 特征），然后各自继续算。多保真度则像给答案盖一个“按 PBE 口径还是 r²SCAN 口径”的印章——同一个人、同一套知识，只是最后按不同口径报数。","arch":{"geometry":"边向量 r_ij（模型直接输入并对其求导）→ 长度：8 个可训练 Bessel × 截断包络（XPLOR 或多项式 p=6）；方向：实球谐 Y_l^m（l ≤ l_max）","equivariance":"等变（e3nn irreps + CG 张量积）；MF-ompa / Omni 区分宇称（O(3)），SevenNet-0 / l3i5 的 is_parity=False 只保证 SO(3)","lmax":"SevenNet-0 为 2；l3i5 / MF-ompa / Omni 为 3（边球谐与隐藏特征共用）；代码默认 1","bodyOrder":"每层消息对邻居特征线性（2 体 + 角度），体序靠多层堆叠 + 门控非线性逐层提升（同 NequIP）","layers":"5（SevenNet-0 / l3i5 / MF-ompa / Omni）；Omni-i8 为 8、Omni-i12 为 12；代码默认 3","cutoff":"5 Å（SevenNet-0 / l3i5）；6 Å（MF-ompa / Omni）；Nano 有 4.5–6 Å 四档；代码默认 4.5 Å","receptiveField":"T × r_c：5×5=25 Å（SevenNet-0）、5×6=30 Å（MF-ompa）、12×6=72 Å（Omni-i12）","message":"Σ_j MLP(e(r_ij)) ⊙ [W₁h_j ⊗_CG Y(r̂_ij)] / n̄（uvu 路径，除以平均邻居数）→ W₂ + 自连接（linear 或 nequip）→ Gate","readout":"最后一层只留 128×0e → 两个无偏置线性层（128→64→1）→ 逐元素（多保真度时逐任务）scale/shift → 求和","forces":"conservative","forcesDetail":"一次 autograd 得到 f_ij = ∂E/∂r_ij，按边起点加、终点减 scatter 成 F = −∂E/∂R；LAMMPS 并行版逐层反传 + reverse_comm","stress":"σ = (1/V) Σ_边 r_ij ⊗ f_ij，与力共用同一次反传；可输出逐原子维里（compute_atomic_virial）","longRange":"无静电 / 电荷模块，仅靠 T × r_c 的消息传递感受野","dispersion":"官方 CUDA 版 Grimme D3（BJ / zero 阻尼，默认 PBE 参数）：SevenNetD3Calculator、LAMMPS pair_style d3、TorchSim SevenNetD3Model","chargeSpin":"无总电荷 / 自旋输入；MF / Omni 多一个任务（modal）one-hot 作为全局条件","otherOutputs":"原子能、逐原子维里（stresses）；同一结构在不同任务（PBE+U / r²SCAN / ωB97M-V 等）下的 E/F/S","strictlyLocal":false,"complexity":"O(T·N·M·C·P_TP)：每层每条边一次 uvu 张量积；P_TP 随 l_max 增长（文档称 l3i5 比 SevenNet-0 慢约 4 倍）","accel":"FlashTP（文档称最高约 4×）/ cuEquivariance / OpenEquivariance / LunaTP；LAMMPS e3gnn、e3gnn/parallel（多 GPU）、ML-IAP；ASE、TorchSim；CUDA D3"},"scores":{"speed":{"v":2,"why":"基础模型 5 层（Omni-i12 为 12 层）、l_max=3，每层每条边都做球谐张量积，属深层等变网络；SevenNet-0（l_max=2、0.84M 参数）与蒸馏版 Nano 快得多，FlashTP/cuEq 内核可进一步提速。"},"expressiveness":{"v":4,"why":"严格等变 + l_max=3 角分辨率 + 5–12 层堆叠，精度高；但与 NequIP 一样每层只做 2 体张量积，体序靠堆层而非像 MACE 那样单层显式构造。"},"longRange":{"v":3,"why":"无静电、无电荷输入；官方提供 CUDA 加速的 D3 外挂（ASE / LAMMPS / TorchSim），外加 25–72 Å 的消息传递感受野。"},"scalability":{"v":4,"why":"为消息传递势专门设计的空间分解并行（e3gnn/parallel）：每层前向交换 ghost 特征、反向回传 ghost 梯度，可多 GPU 跑大体系；但非严格局域，每层都要通信，不及 Allegro / NEP 类。"},"physics":{"v":4,"why":"保守力（对边向量自动微分）、平滑截断包络、原子能求和保证广延性、张量积严格等变；但没有 ZBL 近核排斥，且 is_parity=False 的模型只保证 SO(3) 等变。"},"coverage":{"v":2,"why":"官方输出能量、原子能、力、应力与逐原子维里，外加多保真度任务通道；没有偶极、电荷、磁矩等额外读出头。"}},"steps":[{"stage":"graph","title":"输入与邻居图：ASE 原子 → 带周期平移的边列表","plain":"SevenNetCalculator 收到 ASE Atoms 后，用 matscipy（未安装时退回 ASE）的 neighbour_list 找出所有距离小于 r_c 的有向原子对，直接得到边索引 (i, j)、边向量 r_ij = r_j − r_i + S·C 与晶胞体积；非周期方向会把晶胞人为放大，避免与自己的镜像成边。多保真度模型还要附上任务名 modal。注意 SevenNet 的模型以边向量（而不是坐标）为输入，后面的力和应力都对这些边向量求导。","math":"\\mathcal N(i)=\\{\\,j:\\ \\lVert\\mathbf r_{ij}\\rVert<r_c\\,\\},\\qquad \\mathbf r_{ij}=\\mathbf r_j-\\mathbf r_i+\\mathbf S_{ij}\\mathbf C","code":[{"repo":"SevenNet","file":"sevenn/calculator.py","start":234,"end":249,"lang":"python","excerpt":"def calculate(self, atoms=None, properties=None, system_changes=all_changes):\n    # call parent class to set necessary atom attributes\n    Calculator.calculate(self, atoms, properties, system_changes)\n    if atoms is None:\n        raise ValueError('No atoms to evaluate')\n    data = AtomGraphData.from_numpy_dict(\n        unlabeled_atoms_to_graph(atoms, self.cutoff, with_shift=False)\n    )\n    if self.modal:\n        data[KEY.DATA_MODALITY] = self.modal\n\n    data.to(self.device)  # type: ignore\n\n    output = self.model(data)\n    self.results = self.output_to_results(output)\n","caption":"SevenNetCalculator.calculate：Atoms → 图（可附 modal）→ 模型","url":"https://github.com/MDIL-SNU/SevenNet/blob/8207c8a6c0557812a3e4722ca025200e08acbdf3/sevenn/calculator.py#L234-L249"},{"repo":"SevenNet","file":"sevenn/train/dataload.py","start":32,"end":61,"lang":"python","excerpt":"def _graph_build_matscipy(cutoff: float, pbc, cell, pos):\n    pbc_x = pbc[0]\n    pbc_y = pbc[1]\n    pbc_z = pbc[2]\n\n    identity = np.identity(3, dtype=float)\n    max_positions = np.max(np.absolute(pos)) + 1\n\n    # Extend cell in non-periodic directions\n    # For models with more than 5 layers,\n    # the multiplicative constant needs to be increased.\n    if not pbc_x:\n        cell[0, :] = max_positions * 5 * cutoff * identity[0, :]\n    if not pbc_y:\n        cell[1, :] = max_positions * 5 * cutoff * identity[1, :]\n    if not pbc_z:\n        cell[2, :] = max_positions * 5 * cutoff * identity[2, :]\n    # it does not have self-interaction\n    edge_src, edge_dst, edge_vec, shifts = neighbour_list(\n        quantities='ijDS',\n        pbc=pbc,\n        cell=cell,\n        positions=pos,\n        cutoff=cutoff,\n    )\n    # dtype issue\n    edge_src = edge_src.astype(np.int64)\n    edge_dst = edge_dst.astype(np.int64)\n\n    return edge_src, edge_dst, edge_vec, shifts","caption":"matscipy 近邻表（非周期方向放大晶胞）","url":"https://github.com/MDIL-SNU/SevenNet/blob/8207c8a6c0557812a3e4722ca025200e08acbdf3/sevenn/train/dataload.py#L32-L61"},{"repo":"SevenNet","file":"sevenn/train/dataload.py","start":102,"end":123,"lang":"python","excerpt":"def unlabeled_atoms_to_graph(\n    atoms: ase.Atoms, cutoff: float, with_shift: bool = False\n):\n    pos = atoms.get_positions()\n    cell = np.array(atoms.get_cell())\n    pbc = atoms.get_pbc()\n\n    edge_src, edge_dst, edge_vec, shift = _graph_build_f(cutoff, pbc, cell, pos)\n\n    edge_idx = np.array([edge_src, edge_dst])\n\n    atomic_numbers = atoms.get_atomic_numbers()\n\n    data = {\n        KEY.NODE_FEATURE: atomic_numbers,  # just placeholder\n        KEY.ATOMIC_NUMBERS: atomic_numbers,\n        KEY.POS: pos,\n        KEY.EDGE_IDX: edge_idx,\n        KEY.EDGE_VEC: edge_vec,\n        KEY.CELL_VOLUME: _correct_scalar(atoms.cell.volume),\n        KEY.NUM_ATOMS: _correct_scalar(len(atomic_numbers)),\n    }","caption":"unlabeled_atoms_to_graph：边索引、边向量、体积","url":"https://github.com/MDIL-SNU/SevenNet/blob/8207c8a6c0557812a3e4722ca025200e08acbdf3/sevenn/train/dataload.py#L102-L123"}]},{"stage":"geometry","title":"几何编码：距离 → 可训练 Bessel × 截断包络；方向 → 球谐","plain":"每条边的长度展开为 8 个正弦型 Bessel 函数（频率以 nπ/r_c 为初值，默认可训练），再乘以截断包络：SevenNet-0 与 MF-ompa 用 XPLOR 开关函数（r < r_on=4.5/5.5 Å 时恒为 1，之后平滑降到 0），l3i5 用 p=6 的多项式包络。方向用 e3nn 实球谐 Y_l^m（l ≤ l_max，component 归一化）编码；球谐在旋转下按 Wigner-D 矩阵精确变换，这是等变性的来源。","math":"e_n(r)=\\frac{2}{r_c}\\frac{\\sin(k_nr)}{r}\\,f_{\\text{cut}}(r),\\ k_n\\overset{\\text{init}}{=}\\frac{n\\pi}{r_c};\\quad f_{\\text{XPLOR}}=\\frac{(r_c^2-r^2)^2(r_c^2+2r^2-3r_{\\text{on}}^2)}{(r_c^2-r_{\\text{on}}^2)^3}\\ (r\\ge r_{\\text{on}});\\qquad Y_l^m(\\hat{\\mathbf r}_{ij}),\\ l\\le l_{\\max}","code":[{"repo":"SevenNet","file":"sevenn/nn/edge_embedding.py","start":86,"end":103,"lang":"python","excerpt":"def __init__(\n    self,\n    cutoff_length: float,\n    bessel_basis_num: int = 8,\n    trainable_coeff: bool = True,\n) -> None:\n    super().__init__()\n    self.num_basis = bessel_basis_num\n    self.prefactor = 2.0 / cutoff_length\n    self.coeffs = torch.FloatTensor([\n        n * math.pi / cutoff_length for n in range(1, bessel_basis_num + 1)\n    ])\n    if trainable_coeff:\n        self.coeffs = nn.Parameter(self.coeffs)\n\ndef forward(self, r: torch.Tensor) -> torch.Tensor:\n    ur = r.unsqueeze(-1)  # to fit dimension\n    return self.prefactor * torch.sin(self.coeffs * ur) / ur","caption":"BesselBasis：可训练频率的 Bessel 基","url":"https://github.com/MDIL-SNU/SevenNet/blob/8207c8a6c0557812a3e4722ca025200e08acbdf3/sevenn/nn/edge_embedding.py#L86-L103"},{"repo":"SevenNet","file":"sevenn/nn/edge_embedding.py","start":150,"end":160,"lang":"python","excerpt":"def forward(self, r: torch.Tensor) -> torch.Tensor:\n    r_sq = r * r\n    r_on_sq = self.r_on * self.r_on\n    r_cut_sq = self.r_cut * self.r_cut\n    return torch.where(\n        r < self.r_on,\n        1.0,\n        (r_cut_sq - r_sq) ** 2\n        * (r_cut_sq + 2 * r_sq - 3 * r_on_sq)\n        / (r_cut_sq - r_on_sq) ** 3,\n    )","caption":"XPLORCutoff：r_on 之后平滑降到 0","url":"https://github.com/MDIL-SNU/SevenNet/blob/8207c8a6c0557812a3e4722ca025200e08acbdf3/sevenn/nn/edge_embedding.py#L150-L160"},{"repo":"SevenNet","file":"sevenn/nn/edge_embedding.py","start":207,"end":217,"lang":"python","excerpt":"def forward(self, data: AtomGraphDataType) -> AtomGraphDataType:\n    rvec = data[KEY.EDGE_VEC]\n    r = torch.linalg.norm(data[KEY.EDGE_VEC], dim=-1)\n    data[KEY.EDGE_LENGTH] = r\n\n    data[KEY.EDGE_EMBEDDING] = self.basis_function(\n        r\n    ) * self.cutoff_function(r).unsqueeze(-1)\n    data[KEY.EDGE_ATTR] = self.spherical(rvec)\n\n    return data","caption":"EdgeEmbedding.forward：径向基 × 包络 + 球谐","url":"https://github.com/MDIL-SNU/SevenNet/blob/8207c8a6c0557812a3e4722ca025200e08acbdf3/sevenn/nn/edge_embedding.py#L207-L217"}]},{"stage":"embedding","title":"元素嵌入：one-hot(Z) → 128 维标量通道","plain":"原子序数先按 type_map 映射为类型编号再变成 one-hot，一个无偏置线性层把它变成初始特征 h⁽⁰⁾（128×0e，只有标量）。同一个 one-hot 还被保存为节点属性 a_i（供 nequip 式自连接做张量积）和类型索引（供逐元素 scale/shift 查表）。","math":"h_i^{(0)}=W_{\\text{emb}}\\,\\mathrm{onehot}(Z_i)\\in\\mathbb R^{128}\\ (0e),\\qquad a_i=\\mathrm{onehot}(Z_i)","code":[{"repo":"SevenNet","file":"sevenn/model_build.py","start":532,"end":555,"lang":"python","excerpt":"one_hot_irreps = Irreps(f'{num_species}x0e')\nirreps_x = (\n    Irreps(f'{feature_multiplicity}x0e')\n    if irreps_manual is None\n    else irreps_manual[0]\n)\n\nlayers.update(\n    {\n        'onehot_idx_to_onehot': OnehotEmbedding(\n            num_classes=num_species,\n            data_key_x=KEY.NODE_FEATURE,\n            data_key_out=KEY.NODE_FEATURE,\n            data_key_save=KEY.ATOM_TYPE,  # atomic numbers\n            data_key_additional=KEY.NODE_ATTR,  # one-hot embeddings\n        ),\n        'onehot_to_feature_x': IrrepsLinear(\n            irreps_in=one_hot_irreps,\n            irreps_out=irreps_x,\n            data_key_in=KEY.NODE_FEATURE,\n            biases=use_bias_in_linear,\n        ),\n    }\n)","caption":"one-hot → 线性嵌入（初始 irreps 为 128x0e）","url":"https://github.com/MDIL-SNU/SevenNet/blob/8207c8a6c0557812a3e4722ca025200e08acbdf3/sevenn/model_build.py#L532-L555"},{"repo":"SevenNet","file":"sevenn/nn/node_embedding.py","start":44,"end":53,"lang":"python","excerpt":"def forward(self, data: AtomGraphDataType) -> AtomGraphDataType:\n    inp = data[self.key_x]\n    embd = torch.nn.functional.one_hot(inp, self.num_classes)\n    embd = embd.float()\n    data[self.key_output] = embd\n    if self.key_additional_output is not None:\n        data[self.key_additional_output] = embd  # for self-connection\n    if self.key_save is not None:\n        data[self.key_save] = inp  # for elemwise shift scale\n    return data","caption":"OnehotEmbedding：同时保存节点属性与类型索引","url":"https://github.com/MDIL-SNU/SevenNet/blob/8207c8a6c0557812a3e4722ca025200e08acbdf3/sevenn/nn/node_embedding.py#L44-L53"}]},{"stage":"embedding","title":"多保真度：把“任务 / 泛函”标签拼进线性层","plain":"MF-0 / MF-ompa / Omni 把训练数据的来源（如 mpa、omat24、matpes_r2scan、omol25_low）编码成 modality one-hot。patch_modality 把它插在元素嵌入之后，并让选定的 IrrepsLinear（MF-ompa：每层卷积前后的 self_interaction_1/2 与读出第一层）在输入端拼接这串 one-hot。由于拼进去的是 0e 标量，等价于给每个任务学一组只加在标量通道上的偏置；再配合按“任务 × 元素”查表的能量平移。张量积与径向 MLP 等主体参数由所有数据共享，不同 DFT 设定之间的系统差由这些少量参数吸收。","math":"\\mathrm{Lin}\\big([\\,h_i\\Vert\\mathrm{onehot}(m)\\,]\\big)=W h_i+\\mathbf b_m\\ (\\text{仅 }0e),\\qquad E_i=s_{Z_i}\\,\\hat E_i+\\mu_{m,Z_i}","code":[{"repo":"SevenNet","file":"sevenn/model_build.py","start":206,"end":240,"lang":"python","excerpt":"_layers = list(layers.items())\n_layers = _insert_after(\n    'onehot_idx_to_onehot',\n    (\n        'one_hot_modality',\n        OnehotEmbedding(\n            num_classes=config[KEY.NUM_MODALITIES],\n            data_key_x=KEY.MODAL_TYPE,\n            data_key_out=KEY.MODAL_ATTR,\n            data_key_save=None,\n            data_key_additional=None,\n        ),\n    ),\n    _layers,\n)\nlayers = OrderedDict(_layers)\n\nnum_modal = config[KEY.NUM_MODALITIES]\nfor k, module in layers.items():\n    if not isinstance(module, IrrepsLinear):\n        continue\n    if (\n        (cfg[KEY.USE_MODAL_NODE_EMBEDDING] and k.endswith('onehot_to_feature_x'))\n        or (\n            cfg[KEY.USE_MODAL_SELF_INTER_INTRO]\n            and k.endswith('self_interaction_1')\n        )\n        or (\n            cfg[KEY.USE_MODAL_SELF_INTER_OUTRO]\n            and k.endswith('self_interaction_2')\n        )\n        or (cfg[KEY.USE_MODAL_OUTPUT_BLOCK] and k == 'reduce_input_to_hidden')\n    ):\n        module.set_num_modalities(num_modal)\nreturn layers","caption":"patch_modality：插入任务 one-hot，选择哪些线性层带任务输入","url":"https://github.com/MDIL-SNU/SevenNet/blob/8207c8a6c0557812a3e4722ca025200e08acbdf3/sevenn/model_build.py#L206-L240"},{"repo":"SevenNet","file":"sevenn/nn/linear.py","start":65,"end":100,"lang":"python","excerpt":"def set_num_modalities(self, num_modalities: int) -> None:\n    if self.layer_instantiated:\n        raise ValueError('Layer already instantiated, can not change modalities')\n    irreps_in = self._irreps_in_wo_modal + Irreps(f'{num_modalities}x0e')\n    self.num_modalities = num_modalities\n    self.irreps_in = irreps_in\n\ndef _patch_modal_to_data(self, data: AtomGraphDataType) -> AtomGraphDataType:\n    if self._is_batch_data:\n        batch = data[KEY.BATCH]\n        batch_modality_onehot = data[self.key_modal_attr].reshape(\n            -1, self.num_modalities\n        )\n        batch_modality_onehot = batch_modality_onehot.type(\n            data[self.key_input].dtype\n        )\n        data[self.key_input] = torch.cat(\n            [data[self.key_input], batch_modality_onehot[batch]], dim=1\n        )\n    else:\n        modality_onehot = data[self.key_modal_attr].expand(\n            len(data[self.key_input]), -1\n        )\n        modality_onehot = modality_onehot.type(data[self.key_input].dtype)\n        data[self.key_input] = torch.cat(\n            [data[self.key_input], modality_onehot], dim=1\n        )\n    return data\n\ndef forward(self, data: AtomGraphDataType) -> AtomGraphDataType:\n    assert self.linear is not None, 'Layer is not instantiated'\n    if self.num_modalities > 1:\n        data = self._patch_modal_to_data(data)\n\n    data[self.key_output] = self.linear(data[self.key_input])\n    return data","caption":"IrrepsLinear：输入端拼接任务 one-hot（多出 N×0e）","url":"https://github.com/MDIL-SNU/SevenNet/blob/8207c8a6c0557812a3e4722ca025200e08acbdf3/sevenn/nn/linear.py#L65-L100"},{"repo":"SevenNet","file":"sevenn/nn/scale.py","start":375,"end":390,"lang":"python","excerpt":"def forward(self, data: AtomGraphDataType) -> AtomGraphDataType:\n\n    if self._is_batch_data:\n        batch = data[KEY.BATCH]\n        modal_indices = data[self.key_modal_indices][batch]\n    else:\n        modal_indices = data[self.key_modal_indices]\n    atom_indices = data[self.key_atom_indices]\n    shift = (\n        self.shift[modal_indices, atom_indices]\n        if self.use_modal_wise_shift\n        else self.shift[atom_indices]\n    )\n    scale = (\n        self.scale[modal_indices, atom_indices]\n        if self.use_modal_wise_scale","caption":"ModalWiseRescale：按（任务, 元素）查表的 shift","url":"https://github.com/MDIL-SNU/SevenNet/blob/8207c8a6c0557812a3e4722ca025200e08acbdf3/sevenn/nn/scale.py#L375-L390"}]},{"stage":"interaction","title":"交互块 ①：NequIP 式球谐张量积卷积","plain":"核心与 NequIP 相同：先用线性层 W₁ 混合特征，再在每条边上把邻居特征 h_j 与方向球谐 Y(r̂_ij) 做 Clebsch–Gordan 张量积，只保留落在目标 irreps 里的路径（l > l_max 的被丢弃）；每条路径、每个通道的权重由“Bessel 边嵌入 → MLP [8→64→64→路径数]（SiLU）”逐边生成（uvu 模式）。消息按中心原子 scatter 求和后除以平均邻居数（SevenNet-0 为 35.99）。并行模式下先把 ghost 原子特征拼到 x 后面，聚合后再切回本地原子。开启 cuEquivariance 时，gather–张量积–scatter 被融合成一个 SegmentedPolynomial GPU 内核（FlashTP / OpenEquivariance 同理替换此模块）。","math":"m_{i,c\\,l_3m_3}=\\frac{1}{\\bar n}\\sum_{j\\in\\mathcal N(i)}\\sum_{l_1l_2}w^{(l_1l_2\\to l_3)}_{c}(r_{ij})\\sum_{m_1m_2}C^{l_3m_3}_{l_1m_1,l_2m_2}\\,(W_1h_j)_{c\\,l_1m_1}\\,Y_{l_2}^{m_2}(\\hat{\\mathbf r}_{ij}),\\qquad w=\\mathrm{MLP}\\big(e(r_{ij})\\big)","code":[{"repo":"SevenNet","file":"sevenn/nn/convolution.py","start":61,"end":95,"lang":"python","excerpt":"instructions = []\nirreps_mid = []\nweight_numel = 0\nfor i, (mul_x, ir_x) in enumerate(irreps_x):\n    for j, (_, ir_filter) in enumerate(irreps_filter):\n        for ir_out in ir_x * ir_filter:\n            if ir_out in irreps_out:  # here we drop l > lmax\n                k = len(irreps_mid)\n                weight_numel += mul_x * 1  # path shape\n                irreps_mid.append((mul_x, ir_out))\n                instructions.append((i, j, k, 'uvu', True))\n\nirreps_mid = Irreps(irreps_mid)\nirreps_mid, p, _ = irreps_mid.sort()  # type: ignore\ninstructions = [\n    (i_in1, i_in2, p[i_out], mode, train)\n    for i_in1, i_in2, i_out, mode, train in instructions\n]\n\n# From v0.11.x, to compatible with cuEquivariance\nself._instructions_before_sort = instructions\ninstructions = sorted(instructions, key=lambda x: x[2])\n\nself.convolution_kwargs = dict(\n    irreps_in1=irreps_x,\n    irreps_in2=irreps_filter,\n    irreps_out=irreps_mid,\n    instructions=instructions,\n    shared_weights=False,\n    internal_weights=False,\n)\n\nself.weight_nn_kwargs = dict(\n    hs=weight_layer_input_to_hidden + [weight_numel], act=weight_layer_act\n)","caption":"枚举 l_x ⊗ l_filter → l_out 路径（uvu），径向 MLP 输出全部路径权重","url":"https://github.com/MDIL-SNU/SevenNet/blob/8207c8a6c0557812a3e4722ca025200e08acbdf3/sevenn/nn/convolution.py#L61-L95"},{"repo":"SevenNet","file":"sevenn/nn/convolution.py","start":118,"end":141,"lang":"python","excerpt":"def forward(self, data: AtomGraphDataType) -> AtomGraphDataType:\n    assert self.convolution is not None, 'Convolution is not instantiated'\n    assert self.weight_nn is not None, 'Weight_nn is not instantiated'\n    weight = self.weight_nn(data[self.key_weight_input])\n\n    x = data[self.key_x]\n\n    if self.is_parallel:\n        x = torch.cat([x, data[KEY.NODE_FEATURE_GHOST]])\n\n    edge_src = data[self.key_edge_idx][1]\n    edge_dst = data[self.key_edge_idx][0]\n\n    message = self.convolution(x[edge_src], data[self.key_filter], weight)\n\n    x = message_gather(x, edge_dst, message)\n\n    x = x.div(self.denominator)\n\n    if self.is_parallel:\n        x = torch.tensor_split(x, data[KEY.NLOCAL])[0]\n\n    data[self.key_x] = x\n    return data","caption":"IrrepsConvolution.forward：逐边张量积 → scatter → 除以 n̄（并行时拼接 ghost）","url":"https://github.com/MDIL-SNU/SevenNet/blob/8207c8a6c0557812a3e4722ca025200e08acbdf3/sevenn/nn/convolution.py#L118-L141"},{"repo":"SevenNet","file":"sevenn/nn/cue_helper.py","start":107,"end":124,"lang":"python","excerpt":"    self.f = cuet.SegmentedPolynomial(poly, method=tp_method)\n\ndef forward(\n    self,\n    x: torch.Tensor,\n    filter: torch.Tensor,\n    w: torch.Tensor,\n    edge_src: torch.Tensor,\n    edge_dst: torch.Tensor,\n) -> torch.Tensor:\n    xt = self.t_in(x)\n    o = self.f(\n        [w, xt, filter],\n        {1: edge_src.to(torch.int64)},\n        {0: xt},\n        {0: edge_dst.to(torch.int64)},\n    )[0]\n    return self.t_out(o)","caption":"cuEquivariance：融合 gather + 张量积 + scatter","url":"https://github.com/MDIL-SNU/SevenNet/blob/8207c8a6c0557812a3e4722ca025200e08acbdf3/sevenn/nn/cue_helper.py#L107-L124"}]},{"stage":"interaction","title":"交互块 ②：线性自连接 + Gate 门控（与 NequIP 的主要差别）","plain":"卷积结果经线性层 W₂ 升维到 Gate 所需的 irreps，再加上自连接 SC。NequIP 原版（以及 MF-ompa 的 self_connection_type: nequip）用“特征 ⊗ 元素 one-hot”的全连接张量积，含大量元素相关参数；SevenNet-0 / l3i5 换成普通线性层（linear），Matbench 模型卡称参数从约 1624 万（GNoME 式）降到 84 万。最后是 e3nn Gate：标量通道直接过 SiLU（偶）/ tanh（奇），l>0 通道乘以额外标量算出的门值——只缩放大小、不改方向，仍然等变。","math":"h_i'=W_2\\,m_i+\\mathrm{SC}(h_i),\\quad \\mathrm{SC}=W_{\\text{sc}}h_i\\ (\\text{linear})\\ \\text{或}\\ \\mathrm{FCTP}(h_i,a_i)\\ (\\text{nequip});\\qquad h_i^{(t+1)}=\\sigma\\big(h'_{i,0}\\big)\\oplus\\sigma_g(g_i)\\,h'_{i,l>0}","code":[{"repo":"SevenNet","file":"sevenn/nn/interaction_blocks.py","start":36,"end":76,"lang":"python","excerpt":"sc_intro, sc_outro = self_connection_pair\n\ngate_layer = EquivariantGate(irreps_out, act_scalar, act_gate)\nirreps_for_gate_in = gate_layer.get_gate_irreps_in()\n\nblock[f'{t}_self_connection_intro'] = sc_intro(\n    irreps_x,\n    irreps_operand=irreps_node_attr,\n    irreps_out=irreps_for_gate_in,\n)\n\nblock[f'{t}_self_interaction_1'] = IrrepsLinear(\n    irreps_x, irreps_x,\n    data_key_in=data_key_x,\n    biases=bias_in_linear,\n)\n\n# convolution part, l>lmax is dropped as defined in irreps_out\nblock[f'{t}_convolution'] = IrrepsConvolution(\n    irreps_x=irreps_x,\n    irreps_filter=irreps_filter,\n    irreps_out=irreps_out_tp,\n    data_key_weight_input=data_key_weight_input,\n    weight_layer_input_to_hidden=weight_nn_layers,\n    weight_layer_act=act_radial,\n    denominator=conv_denominator,\n    train_denominator=train_conv_denominator,\n    is_parallel=parallel,\n    **conv_kwargs,\n)\n\n# irreps of x increase to gate_irreps_in\nblock[f'{t}_self_interaction_2'] = IrrepsLinear(\n    irreps_out_tp,\n    irreps_for_gate_in,\n    data_key_in=data_key_x,\n    biases=bias_in_linear,\n)\n\nblock[f'{t}_self_connection_outro'] = sc_outro()\nblock[f'{t}_equivariant_gate'] = gate_layer","caption":"一个交互块：SC intro → W₁ → 卷积 → W₂ → SC outro → Gate","url":"https://github.com/MDIL-SNU/SevenNet/blob/8207c8a6c0557812a3e4722ca025200e08acbdf3/sevenn/nn/interaction_blocks.py#L36-L76"},{"repo":"SevenNet","file":"sevenn/nn/self_connection.py","start":100,"end":114,"lang":"python","excerpt":"def instantiate(self) -> None:\n    if self.linear is not None:\n        raise ValueError('Linear layer already exists')\n    self.linear = self.linear_cls(\n        self.irreps_in, self.irreps_out, **self.linear_kwargs\n    )\n    self.layer_instantiated = True\n\ndef forward(self, data: AtomGraphDataType) -> AtomGraphDataType:\n    assert self.linear is not None, 'Layer is not instantiated'\n\n    x = data[self.key_x]\n    data[KEY.SELF_CONNECTION_TEMP] = self.linear(x)\n\n    return data","caption":"SelfConnectionLinearIntro：线性自连接（SevenNet-0 / l3i5）","url":"https://github.com/MDIL-SNU/SevenNet/blob/8207c8a6c0557812a3e4722ca025200e08acbdf3/sevenn/nn/self_connection.py#L100-L114"},{"repo":"SevenNet","file":"sevenn/nn/equivariant_gate.py","start":26,"end":49,"lang":"python","excerpt":"irreps_gated_elem = []\nirreps_scalars_elem = []\n# non scalar irreps > gated / scalar irreps > scalars\nfor mul, irreps in irreps_x:\n    if irreps.l > 0:\n        irreps_gated_elem.append((mul, irreps))\n    else:\n        irreps_scalars_elem.append((mul, irreps))\nirreps_scalars = Irreps(irreps_scalars_elem)\nirreps_gated = Irreps(irreps_gated_elem)\n\nirreps_gates_parity = 1 if '0e' in irreps_scalars else -1\nirreps_gates = Irreps(\n    [(mul, (0, irreps_gates_parity)) for mul, _ in irreps_gated]\n)\n\nact_scalars = [\n    act_scalar_dict[parity_map[p]] for _, (_, p) in irreps_scalars\n]\nact_gates = [act_gate_dict[parity_map[p]] for _, (_, p) in irreps_gates]\n\nself.gate = Gate(\n    irreps_scalars, act_scalars, irreps_gates, act_gates, irreps_gated\n)","caption":"EquivariantGate：标量激活 + 门控 l>0 通道","url":"https://github.com/MDIL-SNU/SevenNet/blob/8207c8a6c0557812a3e4722ca025200e08acbdf3/sevenn/nn/equivariant_gate.py#L26-L49"}]},{"stage":"readout","title":"逐层堆叠与读出：最后一层只留标量","plain":"交互块重复 T 次（5 层；Omni-i12 为 12 层），各层输出 irreps 由 l_max 与 irreps_manual 决定；最后一层强制 lmax_node=0、只保留偶宇称，即只输出 128 个 0e 标量。读出是两个无偏置线性层（128→64→1），中间没有激活，把这些旋转不变量变成每个原子的（缩放前）能量。与 MACE 的逐层读出不同，只读最后一层。","math":"E_i^{\\text{NN}}=W_b\\,W_a\\,h_i^{(T)},\\qquad h_i^{(T)}\\in\\mathbb R^{128}\\ (0e),\\ W_a:128\\to64,\\ W_b:64\\to1","code":[{"repo":"SevenNet","file":"sevenn/model_build.py","start":591,"end":634,"lang":"python","excerpt":"for t in range(num_convolution_layer):\n    param_interaction_block.update(\n        {\n            'irreps_x': irreps_x,\n            't': t,\n            'conv_denominator': conv_denominator[t],\n            'self_connection_pair': self_connection_pair_list[t],\n        }\n    )\n    if interaction_type == 'nequip':\n        parity_mode = 'full'\n        fix_multiplicity = False\n        if t == num_convolution_layer - 1:\n            lmax_node = 0\n            parity_mode = 'even'\n        # TODO: irreps_manual is applicable to both irreps_out_tp and irreps_out\n        irreps_out = (\n            util.infer_irreps_out(\n                irreps_x,  # type: ignore\n                irreps_filter,\n                lmax_node,  # type: ignore\n                parity_mode,\n                fix_multiplicity=feature_multiplicity,\n            )\n            if irreps_manual is None\n            else irreps_manual[t + 1]\n        )\n        irreps_out_tp = util.infer_irreps_out(\n            irreps_x,  # type: ignore\n            irreps_filter,\n            irreps_out.lmax,  # type: ignore\n            parity_mode,\n            fix_multiplicity,\n        )\n    else:\n        raise ValueError(f'Unknown interaction type: {interaction_type}')\n    param_interaction_block.update(\n        {\n            'irreps_out_tp': irreps_out_tp,\n            'irreps_out': irreps_out,\n        }\n    )\n    layers.update(interaction_builder(**param_interaction_block))\n    irreps_x = irreps_out","caption":"逐层构建交互块；最后一层只输出偶宇称标量","url":"https://github.com/MDIL-SNU/SevenNet/blob/8207c8a6c0557812a3e4722ca025200e08acbdf3/sevenn/model_build.py#L591-L634"},{"repo":"SevenNet","file":"sevenn/model_build.py","start":103,"end":124,"lang":"python","excerpt":"def init_feature_reduce(config: Dict[str, Any], irreps_x: Irreps) -> OrderedDict:\n    # features per node to scalar per node\n    layers = OrderedDict()\n    if config[KEY.READOUT_AS_FCN] is False:\n        hidden_irreps = Irreps([(irreps_x.dim // 2, (0, 1))])\n        layers.update(\n            {\n                'reduce_input_to_hidden': IrrepsLinear(\n                    irreps_x,\n                    hidden_irreps,\n                    data_key_in=KEY.NODE_FEATURE,\n                    biases=config[KEY.USE_BIAS_IN_LINEAR],\n                ),\n                'reduce_hidden_to_energy': IrrepsLinear(\n                    hidden_irreps,\n                    Irreps([(1, (0, 1))]),\n                    data_key_in=KEY.NODE_FEATURE,\n                    data_key_out=KEY.SCALED_ATOMIC_ENERGY,\n                    biases=config[KEY.USE_BIAS_IN_LINEAR],\n                ),\n            }\n        )","caption":"init_feature_reduce：两级线性读出","url":"https://github.com/MDIL-SNU/SevenNet/blob/8207c8a6c0557812a3e4722ca025200e08acbdf3/sevenn/model_build.py#L103-L124"}]},{"stage":"energy","title":"总能：逐元素 scale / shift + 求和","plain":"原子能按元素做 E_i ← s_Z·E_i + μ_Z（SevenNet-0：shift 取逐元素参考能、scale 取 1.730，均不训练；多保真度模型的 shift 还随任务变），再由 AtomReduce 按结构求和。能量写成原子能之和保证了广延性。紧接着模型末尾挂上 ForceStressOutputFromEdge，用同一张计算图求力和应力。","math":"E=\\sum_{i}\\Big(s_{Z_i}E_i^{\\text{NN}}+\\mu_{Z_i}\\Big)\\qquad(\\text{多保真度：}\\mu_{m,Z_i})","code":[{"repo":"SevenNet","file":"sevenn/nn/scale.py","start":182,"end":190,"lang":"python","excerpt":"def forward(self, data: AtomGraphDataType) -> AtomGraphDataType:\n\n    indices = data[self.key_indices]\n    scale = self.scale[indices].view(-1, 1)\n    shift = self.shift[indices].view(-1, 1)\n    inp = data[self.key_input].to(shift.dtype)\n    data[self.key_output] = inp * scale + shift\n\n    return data","caption":"SpeciesWiseRescale：逐元素 scale/shift","url":"https://github.com/MDIL-SNU/SevenNet/blob/8207c8a6c0557812a3e4722ca025200e08acbdf3/sevenn/nn/scale.py#L182-L190"},{"repo":"SevenNet","file":"sevenn/nn/linear.py","start":127,"end":139,"lang":"python","excerpt":"def forward(self, data: AtomGraphDataType) -> AtomGraphDataType:\n    if self._is_batch_data:\n        src = data[self.key_input].squeeze(1)\n        size = int(data[KEY.BATCH].max()) + 1\n        output = torch.zeros(\n            (size),\n            dtype=src.dtype,\n            device=src.device,\n        )\n        output.scatter_reduce_(0, data[KEY.BATCH], src, reduce='sum')\n        data[self.key_output] = output * self.constant\n    else:\n        data[self.key_output] = torch.sum(data[self.key_input]) * self.constant","caption":"AtomReduce：原子能 → 总能","url":"https://github.com/MDIL-SNU/SevenNet/blob/8207c8a6c0557812a3e4722ca025200e08acbdf3/sevenn/nn/linear.py#L127-L139"},{"repo":"SevenNet","file":"sevenn/model_build.py","start":636,"end":650,"lang":"python","excerpt":"layers.update(init_feature_reduce(config, irreps_x))  # type: ignore\n\nlayers.update(\n    {\n        'rescale_atomic_energy': init_shift_scale(config),\n        'reduce_total_enegy': AtomReduce(\n            data_key_in=KEY.ATOMIC_ENERGY,\n            data_key_out=KEY.PRED_TOTAL_ENERGY,\n        ),\n    }\n)\n\ngradient_module = ForceStressOutputFromEdge()\ngrad_key = gradient_module.get_grad_key()\nlayers.update({'force_output': gradient_module})","caption":"读出 → 缩放平移 → 求和 → 力/应力模块","url":"https://github.com/MDIL-SNU/SevenNet/blob/8207c8a6c0557812a3e4722ca025200e08acbdf3/sevenn/model_build.py#L636-L650"}]},{"stage":"forces","title":"力：对边向量自动微分，再按边两端回收","plain":"AtomGraphSequential 在前向开始时就对边向量 r_ij 打开 requires_grad。总能算完后，ForceStressOutputFromEdge 用一次 torch.autograd.grad 得到每条边的 f_ij = ∂E/∂r_ij；由于 r_ij = r_j − r_i + S·C，把 f_ij 按边的起点加、终点减 scatter 回原子，正好是 −∂E/∂r。力因此严格保守；以边为中间变量的好处是同一份 f_ij 还能直接给出应力和逐原子维里，也天然适配 LAMMPS 中“边在本进程、端点可能是 ghost 原子”的情形。","math":"\\mathbf f_{ij}=\\frac{\\partial E}{\\partial\\mathbf r_{ij}},\\qquad \\mathbf F_k=-\\frac{\\partial E}{\\partial\\mathbf r_k}=\\sum_{j}\\mathbf f_{kj}-\\sum_{i}\\mathbf f_{ik}","code":[{"repo":"SevenNet","file":"sevenn/nn/sequential.py","start":157,"end":169,"lang":"python","excerpt":"def _preprocess(self, data: AtomGraphDataType) -> AtomGraphDataType:\n    if self.eval_type_map:\n        atomic_numbers = data[self.key_atomic_numbers]\n        onehot = self._atomic_numbers_to_onehot(atomic_numbers)\n        data[self.key_node_feature] = onehot\n\n    if self.eval_modal_map:\n        self._eval_modal_map(data)\n\n    if self.key_grad is not None:\n        data[self.key_grad].requires_grad_(True)\n\n    return data","caption":"_preprocess：类型/任务映射，并对边向量打开梯度","url":"https://github.com/MDIL-SNU/SevenNet/blob/8207c8a6c0557812a3e4722ca025200e08acbdf3/sevenn/nn/sequential.py#L157-L169"},{"repo":"SevenNet","file":"sevenn/nn/force_output.py","start":171,"end":195,"lang":"python","excerpt":"def forward(self, data: AtomGraphDataType) -> AtomGraphDataType:\n    tot_num = torch.sum(data[KEY.NUM_ATOMS])  # ? item?\n    rij = data[self.key_edge]\n    energy = [(data[self.key_energy]).sum()]\n    edge_idx = data[self.key_edge_idx]\n\n    grad = torch.autograd.grad(\n        energy,\n        [rij],\n        create_graph=self.training,\n        allow_unused=True\n    )\n\n    # make grad is not Optional[Tensor]\n    fij = grad[0]\n\n    if fij is not None:\n        # compute force\n        pf = torch.zeros(tot_num, 3, dtype=fij.dtype, device=fij.device)\n        nf = torch.zeros(tot_num, 3, dtype=fij.dtype, device=fij.device)\n        _edge_src = broadcast(edge_idx[0], fij, 0)\n        _edge_dst = broadcast(edge_idx[1], fij, 0)\n        pf.scatter_reduce_(0, _edge_src, fij, reduce='sum')\n        nf.scatter_reduce_(0, _edge_dst, fij, reduce='sum')\n        data[self.key_force] = pf - nf","caption":"ForceStressOutputFromEdge：∂E/∂r_ij → 原子力","url":"https://github.com/MDIL-SNU/SevenNet/blob/8207c8a6c0557812a3e4722ca025200e08acbdf3/sevenn/nn/force_output.py#L171-L195"}]},{"stage":"stress","title":"应力与逐原子维里：Σ r_ij ⊗ f_ij","plain":"同一份 f_ij 与边向量做外积（xx, yy, zz, xy, yz, zx 六个分量），按边的终点原子累加得到逐原子维里（compute_atomic_virial 时以 stresses 输出），再对整个结构求和、除以体积得到应力；非周期体系体积取 1e-3 下限防止除零。计算器最后取负号并重排成 ASE 的 Voigt 顺序。不需要额外的应变变量，一次反传同时得到力、应力和原子维里（部署给 LAMMPS 串行版时则改用对坐标与晶胞施加虚拟应变的写法）。","math":"\\boldsymbol\\sigma=\\frac{1}{V}\\sum_{(i,j)}\\mathbf r_{ij}\\otimes\\mathbf f_{ij}\\ \\Big(=\\frac1V\\frac{\\partial E}{\\partial\\boldsymbol\\varepsilon}\\Big),\\qquad \\mathbf W_k=-\\sum_{i}\\mathbf r_{ik}\\otimes\\mathbf f_{ik}","code":[{"repo":"SevenNet","file":"sevenn/nn/force_output.py","start":197,"end":237,"lang":"python","excerpt":"# compute virial\ndiag = rij * fij\ns12 = rij[..., 0] * fij[..., 1]\ns23 = rij[..., 1] * fij[..., 2]\ns31 = rij[..., 2] * fij[..., 0]\n# cat last dimension\n_virial = torch.cat([\n    diag,\n    s12.unsqueeze(-1),\n    s23.unsqueeze(-1),\n    s31.unsqueeze(-1)\n], dim=-1)\n\n_s = torch.zeros(tot_num, 6, dtype=fij.dtype, device=fij.device)\n_edge_dst6 = broadcast(edge_idx[1], _virial, 0)\n_s.scatter_reduce_(0, _edge_dst6, _virial, reduce='sum')\nif self.use_atomic_virial:\n    data[self.key_atomic_virial] = torch.neg(_s)\n\nif self._is_batch_data:\n    batch = data[KEY.BATCH]  # for deploy, must be defined first\n    nbatch = int(batch.max().cpu().item()) + 1\n    sout = torch.zeros(\n        (nbatch, 6), dtype=_virial.dtype, device=_virial.device\n    )\n    _batch = broadcast(batch, _s, 0)\n    sout.scatter_reduce_(0, _batch, _s, reduce='sum')\nelse:\n    sout = torch.sum(_s, dim=0)\n\nvolume = data[self.key_cell_volume]\nvlim = 1e-3  # for cell volume = 0 for non PBC structures\nif self._is_batch_data:\n    volume[volume < vlim] = vlim\nelif volume < vlim:\n    volume = torch.tensor(\n        vlim, dtype=volume.dtype, device=volume.device\n    )\n\ndata[self.key_stress] =\\\n    torch.neg(sout) / volume.unsqueeze(-1)","caption":"边维里 → 逐原子维里 → 结构应力","url":"https://github.com/MDIL-SNU/SevenNet/blob/8207c8a6c0557812a3e4722ca025200e08acbdf3/sevenn/nn/force_output.py#L197-L237"},{"repo":"SevenNet","file":"sevenn/calculator.py","start":208,"end":232,"lang":"python","excerpt":"def output_to_results(self, output: Dict[str, torch.Tensor]) -> Dict[str, Any]:\n    energy = output[KEY.PRED_TOTAL_ENERGY].detach().cpu().item()\n    num_atoms = output['num_atoms'].item()\n    atomic_energies = output[KEY.ATOMIC_ENERGY].detach().cpu().numpy().flatten()\n    forces = output[KEY.PRED_FORCE].detach().cpu().numpy()[:num_atoms, :]\n    stress = np.array(\n        (-output[KEY.PRED_STRESS])\n        .detach()\n        .cpu()\n        .numpy()[[0, 1, 2, 4, 5, 3]]  # as voigt notation\n    )\n    results: Dict[str, Any] = {\n        'free_energy': energy,\n        'energy': energy,\n        'energies': atomic_energies,\n        'forces': forces,\n        'stress': stress,\n        'num_edges': output[KEY.EDGE_IDX].shape[1],\n    }\n    if KEY.PRED_ATOMIC_VIRIAL in output:\n        virial = (\n            output[KEY.PRED_ATOMIC_VIRIAL].detach().cpu().numpy()[:num_atoms, :]\n        )\n        results['stresses'] = virial\n    return results","caption":"output_to_results：能量、原子能、力、应力（Voigt）、原子维里","url":"https://github.com/MDIL-SNU/SevenNet/blob/8207c8a6c0557812a3e4722ca025200e08acbdf3/sevenn/calculator.py#L208-L232"}]},{"stage":"forces","title":"并行 MD：逐层 ghost 通信的空间分解（e3gnn/parallel）","plain":"消息传递的难点在于：T 层后原子 i 依赖 T·r_c 内的原子，若只靠加宽 ghost 区，冗余计算随层数暴涨。SevenNet 把模型在每个 self_interaction_1 处切成 T 段（每段重建边嵌入；ghost 原子的初始特征只依赖元素，可本地算出）。在 LAMMPS 中，每段前向之前由 comm_brick 把邻居进程上 ghost 原子的最新节点特征 forward_comm 过来；能量算完后按层倒序反传，每层把对 ghost 特征的梯度 reverse_comm 回其所属进程，与本地梯度相加后继续向前一层传，同时累加 ∂E/∂r_ij，最后由 LAMMPS 组装力与维里。这样每张 GPU 只需保存自己子域的图，可多 GPU 跑大体系 MD。","math":"\\mathbf h^{(t)}_{\\text{ghost}}\\leftarrow\\mathbf h^{(t)}_{\\text{owner}}\\ (\\text{forward\\_comm}),\\qquad \\frac{\\partial E}{\\partial\\mathbf h^{(t)}_{\\text{owner}}}\\mathrel{+}=\\frac{\\partial E}{\\partial\\mathbf h^{(t)}_{\\text{ghost}}}\\ (\\text{reverse\\_comm}),\\qquad \\mathbf f_{ij}=\\sum_{t}\\frac{\\partial E}{\\partial\\mathbf r^{(t)}_{ij}}","code":[{"repo":"SevenNet","file":"sevenn/model_build.py","start":456,"end":465,"lang":"python","excerpt":"# assign modules (before first communications)\n# initialize edge related to retain position gradients\nfor i in range(1, num_convolution_layer):\n    sliced, _layers = slice_until_this(f'{i}_self_interaction_1', _layers)\n    layers_list.append(OrderedDict(sliced))\n    _layers.insert(0, ('edge_embedding', init_edge_embedding(config)))\n\nlayers_list.append(OrderedDict(_layers))\ndel layers_list[-1]['force_output']  # done in LAMMPS\nreturn layers_list","caption":"_to_parallel_model：按层切段，力交给 LAMMPS 端计算","url":"https://github.com/MDIL-SNU/SevenNet/blob/8207c8a6c0557812a3e4722ca025200e08acbdf3/sevenn/model_build.py#L456-L465"},{"repo":"SevenNet","file":"sevenn/pair_e3gnn/pair_e3gnn_parallel.cpp","start":358,"end":390,"lang":"cpp","excerpt":"for (auto it = model_list.begin(); it != model_list.end(); ++it) {\n  if (it == model_list.begin())\n    continue;\n  model_part = *it;\n\n  x_local = output.at(\"x\").toTensor().detach().to(device);\n  x_dim = x_local.size(1); // length of per atom vector(node feature)\n\n  auto ghost_and_extra_x = torch::zeros({ghost_node_num + extra_size, x_dim},\n                                        FLOAT_TYPE.device(device));\n  x_comm = torch::cat({x_local, ghost_and_extra_x}, 0).to(device_comm);\n  comm_brick->forward_comm(this); // populate x_ghost by communication\n\n  // What we got from forward_comm (node feature of ghosts)\n  x_ghost = torch::split_with_sizes(\n      x_comm, {nlocal, ghost_node_num, extra_size}, 0)[1];\n  x_ghost.set_requires_grad(true);\n\n  // prepare next input (output > next input)\n  output.insert_or_assign(\"x_ghost\", x_ghost.to(device));\n  // make another edge_vec to discriminate grad calculation with other\n  // edge_vecs(maybe redundant?)\n  output.insert_or_assign(\"edge_vec\",\n                          output.at(\"edge_vec\").toTensor().clone());\n\n  // save tensors for backprop\n  wrt_tensors.push_back({output.at(\"edge_vec\").toTensor(),\n                         output.at(\"x\").toTensor(),\n                         output.at(\"self_cont_tmp\").toTensor(),\n                         output.at(\"x_ghost\").toTensor()});\n\n  output = model_part.forward({output}).toGenericDict();\n}","caption":"前向：每段之前交换 ghost 原子特征","url":"https://github.com/MDIL-SNU/SevenNet/blob/8207c8a6c0557812a3e4722ca025200e08acbdf3/sevenn/pair_e3gnn/pair_e3gnn_parallel.cpp#L358-L390"},{"repo":"SevenNet","file":"sevenn/pair_e3gnn/pair_e3gnn_parallel.cpp","start":404,"end":441,"lang":"cpp","excerpt":"for (auto rit = wrt_tensors.rbegin(); rit != wrt_tensors.rend(); ++rit) {\n  // edge_vec, x, x_ghost order\n  auto wrt_tensor = *rit;\n  if (rit == wrt_tensors.rbegin()) {\n    grads = torch::autograd::grad({energy_tensor}, wrt_tensor);\n  } else {\n    x_local_save.copy_(x_local);\n    //                            of         wrt         grads_output\n    grads = torch::autograd::grad(of_tensor, wrt_tensor,\n                                  {x_local_save, self_conn_grads});\n  }\n\n  dE_dr = dE_dr + grads.at(0); // accumulate force\n  if (std::distance(rit, wrt_tensors.rend()) == 1)\n    continue; // if last iteration\n\n  of_tensor.clear();\n  of_tensor.push_back(wrt_tensor[1]); // x\n  of_tensor.push_back(wrt_tensor[2]); // self_cont_tmp\n\n  x_local_save = grads.at(1);      // for grads_output\n  x_local = x_local_save.detach(); // grad_outputs & communication\n  x_dim = x_local.size(1);\n\n  self_conn_grads = grads.at(2); // no communication, for grads_output\n\n  x_ghost = grads.at(3).detach(); // yes communication, not for grads_output\n\n  auto extra_x = torch::zeros({extra_size, x_dim}, FLOAT_TYPE.device(device));\n  x_comm = torch::cat({x_local, x_ghost, extra_x}, 0).to(device_comm);\n\n  comm_brick->reverse_comm(this); // completes x_local\n\n  // now x_local is complete (dE_dx), become next grads_output(with\n  // self_conn_grads)\n  x_local = torch::split_with_sizes(\n      x_comm, {nlocal, ghost_node_num, extra_size}, 0)[0];\n}","caption":"反向：逐段 autograd，ghost 梯度回传并累加 dE/dr","url":"https://github.com/MDIL-SNU/SevenNet/blob/8207c8a6c0557812a3e4722ca025200e08acbdf3/sevenn/pair_e3gnn/pair_e3gnn_parallel.cpp#L404-L441"}]},{"stage":"longrange","title":"长程 / 弱相互作用：官方 CUDA D3 外挂","plain":"SevenNet 本体没有任何静电或色散项。官方提供 GPU 版 Grimme D3（从原始 Fortran 代码移植，CUDA + FP32）：ASE 中 SevenNetD3Calculator 用 SumCalculator 把 SevenNet 与 D3Calculator 的能量/力/应力相加（默认 BJ 阻尼、PBE 参数，vdw_cutoff = 9000 au²，即约 95 Bohr；cn_cutoff = 1600 au²，即 40 Bohr）；LAMMPS 中 pair_style d3 与 e3gnn 通过 pair/hybrid 叠加；TorchSim 有 SevenNetD3Model。D3 部分不提供逐原子应力。","math":"E_{\\text{tot}}=E_{\\text{SevenNet}}+E_{\\text{D3}},\\qquad E_{\\text{D3(BJ)}}=-\\sum_{i<j}\\sum_{n=6,8}s_n\\frac{C_n^{ij}}{r_{ij}^{\\,n}+(a_1R_0^{ij}+a_2)^{n}}","code":[{"repo":"SevenNet","file":"sevenn/calculator.py","start":313,"end":334,"lang":"python","excerpt":"d3_calc = D3Calculator(\n    damping_type=damping_type,\n    functional_name=functional_name,\n    vdw_cutoff=vdw_cutoff,\n    cn_cutoff=cn_cutoff,\n    **kwargs,\n)\n\nsevennet_calc = SevenNetCalculator(\n    model=model,\n    file_type=file_type,\n    device=device,\n    modal=modal,\n    enable_cueq=enable_cueq,\n    enable_flash=enable_flash,\n    enable_oeq=enable_oeq,\n    enable_lunatp=enable_lunatp,\n    sevennet_config=sevennet_config,\n    **kwargs,\n)\n\nsuper().__init__([sevennet_calc, d3_calc])","caption":"SevenNetD3Calculator：SevenNet + D3 求和","url":"https://github.com/MDIL-SNU/SevenNet/blob/8207c8a6c0557812a3e4722ca025200e08acbdf3/sevenn/calculator.py#L313-L334"},{"repo":"SevenNet","file":"sevenn/calculator.py","start":260,"end":268,"lang":"python","excerpt":"    enable_oeq: bool = False,\n    enable_lunatp: bool = False,\n    sevennet_config: Optional[Any] = None,\n    damping_type: str = 'damp_bj',\n    functional_name: str = 'pbe',\n    vdw_cutoff: float = 9000,  # au^2, 0.52917726 angstrom = 1 au\n    cn_cutoff: float = 1600,  # au^2, 0.52917726 angstrom = 1 au\n    **kwargs,  # pass extra kwargs to both calculators\n) -> None:","caption":"D3 默认参数：damp_bj、pbe、截断（单位 au²）","url":"https://github.com/MDIL-SNU/SevenNet/blob/8207c8a6c0557812a3e4722ca025200e08acbdf3/sevenn/calculator.py#L260-L268"}]}],"hyper":[{"name":"cutoff r_c","value":"5.0 Å（SevenNet-0 / l3i5）；6.0 Å（MF-ompa / Omni）；代码默认 4.5 Å","note":"截断半径（与 Matbench 模型卡 graph_construction_radius 一致）","code":{"repo":"SevenNet","file":"sevenn/presets/mf_ompa_fine_tune.yaml","start":2,"end":5,"lang":"yaml","excerpt":"model:\n    # parameters of SevenNet-MF-ompa, should not be changed\n    cutoff: 6.0\n    channel: 128","caption":"","url":"https://github.com/MDIL-SNU/SevenNet/blob/8207c8a6c0557812a3e4722ca025200e08acbdf3/sevenn/presets/mf_ompa_fine_tune.yaml#L2-L5"}},{"name":"num_convolution_layer","value":"5（SevenNet-0 / l3i5 / MF-ompa / Omni）；Omni-i8 为 8、Omni-i12 为 12；代码默认 3","note":"交互块层数","code":{"repo":"SevenNet","file":"sevenn/presets/sevennet-0.yaml","start":2,"end":15,"lang":"yaml","excerpt":"model:\n    chemical_species: 'auto'\n    cutoff: 5.0\n    channel: 128\n    is_parity: False\n    lmax: 2\n    num_convolution_layer: 5\n    irreps_manual:\n        - \"128x0e\"\n        - \"128x0e+64x1e+32x2e\"\n        - \"128x0e+64x1e+32x2e\"\n        - \"128x0e+64x1e+32x2e\"\n        - \"128x0e+64x1e+32x2e\"\n        - \"128x0e\"","caption":"","url":"https://github.com/MDIL-SNU/SevenNet/blob/8207c8a6c0557812a3e4722ca025200e08acbdf3/sevenn/presets/sevennet-0.yaml#L2-L15"}},{"name":"lmax","value":"2（SevenNet-0）；3（l3i5 / MF-ompa / Omni）；代码默认 1","note":"边球谐与隐藏特征最高阶","code":{"repo":"SevenNet","file":"sevenn/presets/sevennet-l3i5.yaml","start":4,"end":15,"lang":"yaml","excerpt":"cutoff: 5.0\nirreps_manual:\n- 128x0e\n- 128x0e+64x1e+32x2e+32x3e\n- 128x0e+64x1e+32x2e+32x3e\n- 128x0e+64x1e+32x2e+32x3e\n- 128x0e+64x1e+32x2e+32x3e\n- 128x0e\nchannel: 128\nlmax: 3\nnum_convolution_layer: 5\nis_parity: false","caption":"","url":"https://github.com/MDIL-SNU/SevenNet/blob/8207c8a6c0557812a3e4722ca025200e08acbdf3/sevenn/presets/sevennet-l3i5.yaml#L4-L15"}},{"name":"irreps（各层特征）","value":"SevenNet-0：128x0e+64x1e+32x2e；l3i5 再加 32x3e；MF-ompa 中间层奇偶宇称都有（如 128x0e+64x1o+64x1e+32x2o+32x2e+32x3o+32x3e）；首尾层 128x0e","note":"irreps_manual 手工指定","code":{"repo":"SevenNet","file":"sevenn/presets/mf_ompa_fine_tune.yaml","start":6,"end":12,"lang":"yaml","excerpt":"irreps_manual:\n- 128x0e\n- 128x0e+64x1o+32x2e+32x3o\n- 128x0e+64x1o+64x1e+32x2o+32x2e+32x3o+32x3e\n- 128x0o+128x0e+64x1o+64x1e+32x2o+32x2e+32x3o+32x3e\n- 128x0e+64x1o+32x2e+32x3o\n- 128x0e","caption":"","url":"https://github.com/MDIL-SNU/SevenNet/blob/8207c8a6c0557812a3e4722ca025200e08acbdf3/sevenn/presets/mf_ompa_fine_tune.yaml#L6-L12"}},{"name":"is_parity","value":"False（SevenNet-0 / l3i5）；True（MF-ompa）；代码默认 True","note":"是否区分奇偶宇称（False 时只保证 SO(3) 等变）","code":{"repo":"SevenNet","file":"sevenn/presets/mf_ompa_fine_tune.yaml","start":13,"end":17,"lang":"yaml","excerpt":"lmax: 3\nlmax_edge: -1\nlmax_node: -1\nis_parity: true\nnum_convolution_layer: 5","caption":"","url":"https://github.com/MDIL-SNU/SevenNet/blob/8207c8a6c0557812a3e4722ca025200e08acbdf3/sevenn/presets/mf_ompa_fine_tune.yaml#L13-L17"}},{"name":"radial basis × cutoff","value":"8 个 Bessel（频率可训练）× XPLOR（r_on = 4.5 Å：SevenNet-0；5.5 Å：MF-ompa）或多项式 p=6（l3i5）","note":"径向编码与平滑截断","code":{"repo":"SevenNet","file":"sevenn/presets/sevennet-0.yaml","start":17,"end":23,"lang":"yaml","excerpt":"weight_nn_hidden_neurons: [64, 64]\nradial_basis:\n    radial_basis_name: 'bessel'\n    bessel_basis_num: 8\ncutoff_function:\n    cutoff_function_name: 'XPLOR'\n    cutoff_on: 4.5","caption":"","url":"https://github.com/MDIL-SNU/SevenNet/blob/8207c8a6c0557812a3e4722ca025200e08acbdf3/sevenn/presets/sevennet-0.yaml#L17-L23"}},{"name":"weight_nn_hidden_neurons","value":"[64, 64]（SiLU）","note":"Bessel 边嵌入 → 张量积逐边权重","code":{"repo":"SevenNet","file":"sevenn/_const.py","start":112,"end":134,"lang":"python","excerpt":"DEFAULT_E3_EQUIVARIANT_MODEL_CONFIG = {\n    KEY.CUTOFF: 4.5,\n    KEY.NODE_FEATURE_MULTIPLICITY: 32,\n    KEY.IRREPS_MANUAL: False,\n    KEY.LMAX: 1,\n    KEY.LMAX_EDGE: -1,  # -1 means lmax_edge = lmax\n    KEY.LMAX_NODE: -1,  # -1 means lmax_node = lmax\n    KEY.IS_PARITY: True,\n    KEY.NUM_CONVOLUTION: 3,\n    KEY.RADIAL_BASIS: {\n        KEY.RADIAL_BASIS_NAME: 'bessel',\n    },\n    KEY.CUTOFF_FUNCTION: {\n        KEY.CUTOFF_FUNCTION_NAME: 'poly_cut',\n    },\n    KEY.ACTIVATION_RADIAL: 'silu',\n    KEY.ACTIVATION_SCARLAR: {'e': 'silu', 'o': 'tanh'},\n    KEY.ACTIVATION_GATE: {'e': 'silu', 'o': 'tanh'},\n    KEY.CONVOLUTION_WEIGHT_NN_HIDDEN_NEURONS: [64, 64],\n    # KEY.AVG_NUM_NEIGH: True,  # deprecated\n    # KEY.TRAIN_AVG_NUM_NEIGH: False,  # deprecated\n    KEY.CONV_DENOMINATOR: 'avg_num_neigh',\n    KEY.TRAIN_DENOMINTAOR: False,","caption":"","url":"https://github.com/MDIL-SNU/SevenNet/blob/8207c8a6c0557812a3e4722ca025200e08acbdf3/sevenn/_const.py#L112-L134"}},{"name":"conv_denominator","value":"avg_num_neigh（SevenNet-0 为 35.989574）","note":"聚合后除以平均邻居数（可选 sqrt_avg_num_neigh）","code":{"repo":"SevenNet","file":"sevenn/pretrained_potentials/SevenNet_0__11Jul2024/pre_train.yaml","start":21,"end":30,"lang":"yaml","excerpt":"    cutoff_function_name: 'XPLOR'\n    cutoff_on: 4.5\n\nact_gate: {'e': 'silu', 'o': 'tanh'}\nact_scalar: {'e': 'silu', 'o': 'tanh'}\n\nconv_denominator: 35.989574  # 'avg_num_neigh'\ntrain_shift_scale: False\ntrain_denominator: False\nself_connection_type: 'linear'","caption":"","url":"https://github.com/MDIL-SNU/SevenNet/blob/8207c8a6c0557812a3e4722ca025200e08acbdf3/sevenn/pretrained_potentials/SevenNet_0__11Jul2024/pre_train.yaml#L21-L30"}},{"name":"self_connection_type","value":"linear（SevenNet-0 / l3i5）；nequip（MF-ompa：特征 ⊗ 元素 one-hot 全连接张量积）","note":"SevenNet 相对 NequIP 的主要减参手段","code":{"repo":"SevenNet","file":"sevenn/presets/mf_ompa_fine_tune.yaml","start":37,"end":43,"lang":"yaml","excerpt":"use_modal_node_embedding: false\nuse_modal_self_inter_intro: true\nuse_modal_self_inter_outro: true\nuse_modal_output_block: true\nreadout_as_fcn: false\nself_connection_type: nequip\ninteraction_type: nequip","caption":"","url":"https://github.com/MDIL-SNU/SevenNet/blob/8207c8a6c0557812a3e4722ca025200e08acbdf3/sevenn/presets/mf_ompa_fine_tune.yaml#L37-L43"}},{"name":"modality 开关（MF-ompa）","value":"use_modal_self_inter_intro / outro / output_block = true；node_embedding = false；另设 use_modal_wise_shift = true","note":"任务 one-hot 拼进哪些线性层","code":{"repo":"SevenNet","file":"sevenn/presets/mf_ompa_fine_tune.yaml","start":37,"end":43,"lang":"yaml","excerpt":"use_modal_node_embedding: false\nuse_modal_self_inter_intro: true\nuse_modal_self_inter_outro: true\nuse_modal_output_block: true\nreadout_as_fcn: false\nself_connection_type: nequip\ninteraction_type: nequip","caption":"","url":"https://github.com/MDIL-SNU/SevenNet/blob/8207c8a6c0557812a3e4722ca025200e08acbdf3/sevenn/presets/mf_ompa_fine_tune.yaml#L37-L43"}},{"name":"shift / scale","value":"SevenNet-0：逐元素参考能 / 1.730（per_atom_energy_std）；MF-ompa：逐任务 × 逐元素 shift","note":"原子能缩放与平移（不训练）","code":{"repo":"SevenNet","file":"sevenn/pretrained_potentials/SevenNet_0__11Jul2024/pre_train.yaml","start":70,"end":74,"lang":"yaml","excerpt":"data:\n    data_shuffle: False\n    batch_size: 128  # per GPU batch size, as the model trained with 32 GPUs, the effective batch size equals 4096.\n    scale: 1.730  # 'per_atom_energy_std'\n    shift: 'elemwise_reference_energies'","caption":"","url":"https://github.com/MDIL-SNU/SevenNet/blob/8207c8a6c0557812a3e4722ca025200e08acbdf3/sevenn/pretrained_potentials/SevenNet_0__11Jul2024/pre_train.yaml#L70-L74"}},{"name":"参数量","value":"SevenNet-0 842,440；l3i5 1,171,144；MF-ompa 25,734,966；Omni-i12 54,921,363","note":"Matbench Discovery 模型卡（Omni-i12 训练：8×H200，每卡 800 h）","code":{"repo":"matbench-discovery","file":"models/sevennet/sevennet-omni-i12.yml","start":67,"end":73,"lang":"yaml","excerpt":"training_sets: [COSMOSDataset]\nmodel_params: 54921363\ntraining_cost:\n  entries:\n  - hardware: NVIDIA H200\n    count: 8\n    hours_per_device: 800.0","caption":"","url":"https://github.com/janosh/matbench-discovery/blob/c70947f7fd176b8914b72c4ec9a974adfa3b4d50/models/sevennet/sevennet-omni-i12.yml#L67-L73"}}],"speedNotes":["FLOPs 主要花在每层每条边的 CG 张量积（uvu）与径向 MLP 上；SevenNet-0（l_max=2、5 层、0.84M 参数）是官方推理最快的老模型，文档称 l3i5（l_max=3）约慢 4 倍；Omni-i12 有 12 层、约 5490 万参数。","相对 NequIP 的减参：SevenNet-0 / l3i5 把自连接里“特征 ⊗ 元素 one-hot”的全连接张量积换成线性层（Matbench 模型卡：约 1624 万 → 84 万参数）；MF-ompa 仍用 nequip 式自连接。","张量积内核可换：FlashTP（文档称最高约 4×）、cuEquivariance（gather–TP–scatter 融合）、OpenEquivariance、LunaTP；文档称约 10³ 原子以下 FlashTP + LAMMPS Torch 更快，更大体系 cuEquivariance + ML-IAP 更快。","多保真度参数只是几个线性层上拼接的任务 one-hot，MF-0 文档称推理开销可忽略；蒸馏得到的 SevenNet-Nano（105k 参数、3 层、l_max=2）文档称比教师模型快一个数量级以上。","力、应力、原子维里共用一次对边向量的反传；D3 用 CUDA + FP32 实现以免拖慢 GPU 上的势函数，但文档说明它暂不支持多 GPU / 多核并行。"],"weakNotes":["截断 5 Å（SevenNet-0 / l3i5）或 6 Å（MF-ompa / Omni），5 层消息传递使感受野约 25–30 Å，Omni-i12 的 12 层可达 72 Å；但网络中没有显式 r⁻⁶ 色散或 r⁻¹ 静电项，感受野外的长程尾巴完全缺失。","SevenNet-0 / l3i5 只用 MPtrj，MF-ompa 用 MPtrj + sAlex + OMat24（PBE/PBE+U），几乎不含 vdW：层状材料、分子晶体、物理吸附应叠加官方 CUDA D3（SevenNetD3Calculator 或 LAMMPS pair_style d3，默认 BJ 阻尼 + PBE 参数）。","Omni 的 13 个任务覆盖 PBE(+U)、RPBE、PBEsol、PBE0、r²SCAN、ωB97M(-V)、PBE-D3（odac23）等；选 omol25_low（ωB97M-V）或 odac23（PBE-D3）这类标签本身已含色散的任务时，再叠加 D3 会重复计算。","没有总电荷 / 自旋输入，也没有电荷平衡或 Ewald 静电；带电缺陷、离子液体、电化学界面风险较大（omol25_high 任务只是“高自旋构型”的数据集标签，并非自旋输入）。","没有 ZBL 近核排斥先验，极短距离行为完全依赖训练数据：Matbench Discovery 双原子测试中 l3i5 排除了 He–He、Omni-i12 排除了 Bi–Bi（原因记为 exploding errors）。"],"downstreamNotes":["保守力 + 平滑截断 → 适合声子与热导率：Matbench Discovery κ_SRME 为 SevenNet-0 0.762、l3i5 0.5496、MF-ompa 0.3171、Omni-i12 0.1917。","稳定性预测与几何优化：Matbench Discovery 全测试集 F1 = 0.719（SevenNet-0）/ 0.751（l3i5）/ 0.884（MF-ompa）/ 0.887（Omni-i12）；弛豫结构 RMSD 0.0848（SevenNet-0）、0.0639（MF-ompa）、0.0618（Omni-i12）。","大体系 MD 是 SevenNet 的主打：LAMMPS e3gnn/parallel 多 GPU 空间分解（文档推荐 CUDA-aware OpenMPI），另有 ML-IAP、ASE 与 TorchSim 批量 MD / 弛豫接口。","多保真度 / 多任务：同一个 Omni 模型可切到 r²SCAN 或 ωB97M-V 任务做更高精度预测；官方还提供带遗忘抑制（经验回放 + EWC / reEWC）的微调框架，适合在小数据上继续学习。","原生应力与逐原子维里 → NPT MD、状态方程、弹性常数；没有偶极 / 极化率 / 磁矩读出头，红外 / 拉曼光谱与磁性体系需另行扩展。"],"strengths":["LAMMPS 多 GPU 空间分解并行，专为消息传递势设计，适合大体系 MD","NequIP 式严格等变，线性自连接大幅减参（SevenNet-0 仅 0.84M 参数）","多保真度 / 多任务：一个 Omni 模型覆盖 PBE(+U)、r²SCAN、ωB97M-V 等 13 个任务","Omni-i12 在 Matbench Discovery 上 κ_SRME 0.1917、F1 0.887","加速生态完善：FlashTP / cuEq / OpenEquivariance / LunaTP、CUDA D3、TorchSim"],"weaknesses":["5–12 层 l_max=3 张量积，推理比 2 层的 MACE、严格局域的 Allegro 更慢","每层都要 ghost 特征通信，并行效率受通信限制","无静电、无电荷/自旋输入，色散只能外挂 D3","无 ZBL 近核排斥；is_parity=False 的模型只保证 SO(3) 等变","除 E/F/S/原子维里外没有额外性质输出"],"pretrained":["SevenNet-0（11Jul2024，MPtrj；ASE 默认模型）","SevenNet-l3i5（MPtrj，l_max=3）","SevenNet-MF-0（MP 的 PBE(+U) + r²SCAN）","SevenNet-MF-ompa（MPtrj + sAlex + OMat24；任务 mpa / omat24）","SevenNet-omat（OMat24）","SevenNet-Omni / Omni-i8 / Omni-i12（15 个开放数据集、13 个任务）","SevenNet-Nano（由 Omni mpa 蒸馏；截断 4.5 / 5.0 / 5.5 / 6.0 Å）"],"mbdKeys":["sevennet-0","sevennet-l3i5","sevennet-mf-ompa","sevennet-omni-i12"],"arenaKeys":["SevenNet"],"sources":{"SevenNet":{"url":"https://github.com/MDIL-SNU/SevenNet","commit":"8207c8a6c0557812a3e4722ca025200e08acbdf3","date":"2026-10-29"}}};
